UPDATE evaluation_case_attempt
SET replay_task_id = CASE id

        WHEN #{entity.id} THEN #{entity.replayTaskId}

    END,
    execution_task_id = CASE id

        WHEN #{entity.id} THEN #{entity.executionTaskId}

    END,
    capability_segment_id = CASE id

        WHEN #{entity.id} THEN #{entity.capabilitySegmentId}

    END,
    status = CASE id

        WHEN #{entity.id} THEN #{entity.status}

    END,
    started_at = CASE id

        WHEN #{entity.id} THEN #{entity.startedAt}

    END,
    updated_at = CURRENT_TIMESTAMP
WHERE id IN

    #{entity.id}
